Nuevo método que retorna el contexto como un mapa de archivos en vez de un objeto monolítico:

async toSignals(): Promise<Map<string, object>> {
  const output = await this.collectContext();
  const signals = new Map<string, object>();

  for (const ctx of output.contexts) {
    const filename = this.typeToFilename(ctx.type);
    signals.set(filename, {
      generatedAt: ctx.timestamp,
      source: ctx.source,
      type: ctx.type,
      data: ctx.data,
    });
  }

  return signals;
}

private typeToFilename(type: string): string {
  const map: Record<string, string> = {
    'filesystem': 'structure.json',
    'git': 'git.json',
    'package-json': 'stack.json',
    'env': 'env.json',
  };
  return map[type] ?? `${type}.json`;
}

Método toAgentMd() que genera el archivo de entrada del agente con datos reales:

async toAgentMd(projectRoot: string): Promise<string> {
  const output = await this.collectContext();
  // extraer datos clave de los contextos
  const pkg = output.contexts.find(c => c.type === 'package-json')?.data;
  const git = output.contexts.find(c => c.type === 'git')?.data;
  const stack = (pkg as any)?.stack;

  // Leer tarea activa si existe (de context/tasks/active/)
  const activeTasks = this.readActiveTasks(projectRoot);

  return buildAgentMd({ output, pkg, git, stack, activeTasks });
}

El AGENT.md generado es un índice que apunta a los archivos en context/, no un documento autocontenido.

Nuevo flujo en scan():

// 1. Verificar que context/ existe
const contextDir = path.join(options.projectRoot, 'context');
if (!fs.existsSync(contextDir)) {
  console.warn('⚠ context/ no encontrado. Corre primero: context init --project-root=.');
  // continuar con el comportamiento legacy (context.json monolítico)
}

// 2. Obtener señales granulares
const signals = await engine.toSignals();

// 3. Escribir cada señal en su archivo
const signalsDir = path.join(contextDir, 'signals');
fs.mkdirSync(signalsDir, { recursive: true });

for (const [filename, data] of signals.entries()) {
  const filePath = path.join(signalsDir, filename);
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
  console.log(`✓ Signal: context/signals/${filename}`);
}

// 4. Regenerar AGENT.md
const agentMd = await engine.toAgentMd(options.projectRoot);
fs.writeFileSync(path.join(options.projectRoot, 'AGENT.md'), agentMd, 'utf-8');
console.log('✓ AGENT.md actualizado');

// 5. Mantener legacy context.json (deprecación futura)
const legacyJson = await engine.toJSON();
fs.writeFileSync(path.join(contextDir, 'context.json'), legacyJson, 'utf-8');

El scan debe intentar usar los adaptadores ISO si están instalados. Usar dynamic import para no romper si no están disponibles:

try {
  const { StandardsEngine } = await import('@csantisgallegos/context-standards');
  // Intentar cargar cada adaptador ISO
  // Si no están instalados, continuar sin ellos
  // Las señales ISO se escriben en signals/security.json, signals/quality.json, etc.
} catch {
  // context-standards no está instalado, continuar sin compliance
}

Lee los archivos JSON en context/tasks/active/ y retorna sus títulos y estados:

private readActiveTasks(projectRoot: string): Array<{id: string, title: string}> {
  const activeDir = path.join(projectRoot, 'context', 'tasks', 'active');
  if (!fs.existsSync(activeDir)) return [];
  return fs.readdirSync(activeDir)
    .filter(f => f.endsWith('.json') && f !== '.gitkeep')
    .map(f => {
      try {
        const task = JSON.parse(fs.readFileSync(path.join(activeDir, f), 'utf-8'));
        return { id: task.id, title: task.title };
      } catch { return null; }
    })
    .filter(Boolean) as Array<{id: string, title: string}>;
}
